import{sceneryScene}from'./scenery-plan.js';
import{TrailWorld}from'./trail-world.js';import{TrailNavigator}from'./trail-nav.js';import{freshJourney,freshExpedition,orderFor}from'./expedition.js';import{sectionFor,localPoint}from'./traversal-layout.js';import{applyGraphics,graphicsSettings}from'./render-quality.js';import{updateEnvironmentField}from'./environment-field.js';
const $=s=>document.querySelector(s),j=freshJourney();let world,nav,e,busy=false;
function temporaryRoute(){const area=Number($('#area').value),chapter=Number($('#chapter').value),state=freshExpedition(j,'g5u1',area);state.choices.fill('left');state.index=chapter*4;state.completed=Array.from({length:state.index},(_,index)=>({index,id:state.id+':'+index,type:orderFor(state,Math.floor(index/4))[index%4]}));return state;}
function position(){const s=sectionFor(e,e.index),p=localPoint(s,Math.min(10,s.length*.62));nav.restore(p);nav.heading=Math.atan2(s.forward.x,s.forward.z);world.viewRig.yaw=nav.heading;world.viewRig.inputYaw=null;world.setView(false);world.paused=false;}
function restoration(){const chapter=Number($('#chapter').value),completed=$('#restored').checked?Array.from({length:(chapter+1)*4},(_,index)=>({index,id:e.id+':'+index,type:orderFor(e,Math.floor(index/4))[index%4]})):Array.from({length:chapter*4},(_,index)=>({index,id:e.id+':'+index,type:orderFor(e,Math.floor(index/4))[index%4]}));e.completed=completed;updateEnvironmentField(world.environmentField,{player:nav.player,completed,expedition:e,dt:.1,reduced:true});}
function quality(){applyGraphics(world,graphicsSettings({preset:$('#quality').value}),devicePixelRatio);}
async function show(){if(busy)return;busy=true;try{e=temporaryRoute();nav.state=e;nav.enableTraversal('relaxed');world.setArea(e.area);await world.loadForm(Number($('#form').value));position();restoration();quality();$('#caption').textContent=['Whisperwood','Skyreach','Stormglass'][e.area]+' · '+sceneryScene(e.area,Number($('#chapter').value)).name;$('#status').textContent='';}catch(error){console.error(error);$('#status').textContent='The 3D preview could not start. Open it in a browser with WebGL enabled. Your game saves are untouched.';}finally{busy=false;}}
try{e=temporaryRoute();nav=new TrailNavigator(e,()=>{});nav.enableTraversal('relaxed');world=new TrailWorld($('#world'),()=>{},nav);world.onFrame=()=>{world.measurementPhase='explore';};$('#reduced').addEventListener('change',()=>{world.environmentReducedMotion=$('#reduced').checked;});for(const id of ['area','chapter','form'])$('#'+id).addEventListener('change',show);$('#quality').addEventListener('change',quality);$('#restored').addEventListener('change',restoration);$('#recenter').addEventListener('click',position);await show();}catch(error){console.error(error);$('#status').textContent='The 3D preview could not start. Open it in a browser with WebGL enabled. Your game saves are untouched.';}
